  if (PREDICT_TRUE(zero == 0)) {
	// main execution path
  } else {
	// compiler should place this code outside of main execution path
  }

OR:

  if (PREDICT_FALSE(something_rare_or_unexpected_happens)) {
	// compiler should place this code outside of main execution path
  }

