	if (hc4 == NULL) return NULL;   /* not enough memory */
	LZ4HC_init ((LZ4HC_Data_Structure*)hc4, (const BYTE*)inputBuffer);
	((LZ4HC_Data_Structure*)hc4)->inputBuffer = (BYTE*)inputBuffer;
