namespace bcm {

typedef uint8_t  byte;
typedef uint32_t uint;
typedef uint64_t ulonglong;

const char magic[]="BCM1";

class Encoder
{
public:
	uint code;
	uint low;
	uint high;
	std::istream &in;
	std::ostream &out;

	Encoder( std::istream &in, std::ostream &out )
		: code(0), low(0), high(-1), in(in), out(out)
	{}

	void Encode(int bit, uint p)
	{
		const uint mid=low+((ulonglong(high-low)*(p<<14))>>32);

		if (bit)
			high=mid;
		else
			low=mid+1;

		while ((low^high)<(1<<24))
		{
			out.put(low>>24);
			low<<=8;
			high=(high<<8)|255;
		}
	}

	void Flush()
	{
		for (int i=0; i<4; ++i)
		{
			out.put(low>>24);
			low<<=8;
		}
	}

	void Init()
	{
		for (int i=0; i<4; ++i)
			code=(code<<8)|in.get();
	}

	int Decode(uint p)
	{
		const uint mid=low+((ulonglong(high-low)*(p<<14))>>32);

		const int bit=(code<=mid);
		if (bit)
			high=mid;
		else
			low=mid+1;

		while ((low^high)<(1<<24))
		{
			code=(code<<8)|in.get();
			low<<=8;
			high=(high<<8)|255;
		}

		return bit;
	}
};

template<int RATE>
class Counter
{
public:
	int p;

	Counter()
		: p(1<<15)
	{}

	void Update(int bit)
	{
		if (bit)
			p+=(p^65535)>>RATE;
		else
			p-=p>>RATE;
	}
};

class CM: public Encoder
{
public:
	Counter<2> counter0[256];
	Counter<4> counter1[256][256];
	Counter<6> counter2[2][256][17];
	int c1;
	int c2;
	int run;

	CM( std::istream &in, std::ostream &out )
		: Encoder(in, out), c1(0), c2(0), run(0)
	{
		for (int i=0; i<2; ++i)
		{
			for (int j=0; j<256; ++j)
			{
				for (int k=0; k<17; ++k)
					counter2[i][j][k].p=(k-(k==16))<<12;
			}
		}
	}

	void Put(int c)
	{
		if (c1==c2)
			++run;
		else
			run=0;
		const int f=(run>2);

		int ctx=1;
		while (ctx<256)
		{
			const int p0=counter0[ctx].p;
			const int p1=counter1[c1][ctx].p;
			const int p2=counter1[c2][ctx].p;
			const int p=(p0+p0+p0+p0+p1+p1+p1+p2)>>3;

			const int idx=p>>12;
			const int x1=counter2[f][ctx][idx].p;
			const int x2=counter2[f][ctx][idx+1].p;
			const int ssep=x1+(((x2-x1)*(p&4095))>>12);

			const int bit=((c&128)!=0);
			c+=c;
			Encoder::Encode(bit, p+ssep+ssep+ssep);

			counter0[ctx].Update(bit);
			counter1[c1][ctx].Update(bit);
			counter2[f][ctx][idx].Update(bit);
			counter2[f][ctx][idx+1].Update(bit);

			ctx+=ctx+bit;
		}

		c2=c1;
		c1=byte(ctx);
	}

	int Get()
	{
		if (c1==c2)
			++run;
		else
			run=0;
		const int f=(run>2);

		int ctx=1;
		while (ctx<256)
		{
			const int p0=counter0[ctx].p;
			const int p1=counter1[c1][ctx].p;
			const int p2=counter1[c2][ctx].p;
			const int p=(p0+p0+p0+p0+p1+p1+p1+p2)>>3;

			const int idx=p>>12;
			const int x1=counter2[f][ctx][idx].p;
			const int x2=counter2[f][ctx][idx+1].p;
			const int ssep=x1+(((x2-x1)*(p&4095))>>12);

			const int bit=Encoder::Decode(p+ssep+ssep+ssep);

			counter0[ctx].Update(bit);
			counter1[c1][ctx].Update(bit);
			counter2[f][ctx][idx].Update(bit);
			counter2[f][ctx][idx+1].Update(bit);

			ctx+=ctx+bit;
		}

		c2=c1;
		return c1=byte(ctx);
	}
};

bool compress( std::istream &in, std::ostream &out, uint64_t ilen, int b = 20<<20 ) // blocksize (20 MiB)
{
	if (!ilen)
	{
		perror("Invalid size");
		return false;
	}
	if (b>ilen)
		b=int(ilen);

	CM cm( in, out );

	std::vector<byte> vbuf( (b*5), 0 );
	byte *buf = vbuf.data();

	out.put(magic[0]);
	out.put(magic[1]);
	out.put(magic[2]);
	out.put(magic[3]);

	int n;
	for(;;) {
		in.read((char *)buf, b);
		n = in.gcount();
		if( n <= 0 ) {
			break;
		}

		const int p=divbwt(buf, buf, (int*)&buf[b], n, 0,0,0 );
		if (p<1)
		{
			perror("Divbwt failed");
			return false;
		}

		cm.Put(n>>24);
		cm.Put(n>>16);
		cm.Put(n>>8);
		cm.Put(n);
		cm.Put(p>>24);
		cm.Put(p>>16);
		cm.Put(p>>8);
		cm.Put(p);

		for (int i=0; i<n; ++i)
			cm.Put(buf[i]);
	}

	cm.Put(0); // EOF
	cm.Put(0);
	cm.Put(0);
	cm.Put(0);

	cm.Flush();

	return true;
}

bool decompress( std::istream &in, std::ostream &out )
{
	if ((in.get()!=magic[0])
		||(in.get()!=magic[1])
		||(in.get()!=magic[2])
		||(in.get()!=magic[3]))
	{
		perror("Not in BCM format");
		return false;
	}

	CM cm( in, out );
	cm.Init();

	std::vector<byte> vbuf;
	byte* buf=0;
	int b=0;

	for(;;)
	{
		const int n=(cm.Get()<<24)
			|(cm.Get()<<16)
			|(cm.Get()<<8)
			|cm.Get();
		if (n==0)
			break;
		if (b==0)
		{
			vbuf=std::vector<byte>((b=n) * 5, 0);
			buf = vbuf.data();
		}
		const int p=(cm.Get()<<24)
			|(cm.Get()<<16)
			|(cm.Get()<<8)
			|cm.Get();
		if ((n<1)||(n>b)||(p<1)||(p>n))
		{
			perror("File corrupted");
			return false;
		}
		// Inverse BWT
		int t[257]={0};
		for (int i=0; i<n; ++i)
			++t[(buf[i]=cm.Get())+1];
		for (int i=1; i<256; ++i)
			t[i]+=t[i-1];
		int* next=(int*)&buf[b];
		for (int i=0; i<n; ++i)
			next[t[buf[i]]++]=i+(i>=p);
		for (int i=p; i!=0;)
		{
			i=next[i-1];
			out.put(buf[i-(i>=p)]);
		}
	}

	return true;
}

}

