			if (inputs > 2) *sp2 = nextState(s2, bit, 2);
			if (inputs > 3) *sp3 = nextState(s3, bit, 3);
			if (inputs > 4) *sp4 = nextState(s4, bit, 4);
			if (inputs > 5) *sp5 = nextState(s5, bit, 5);
			if (inputs > 6) *sp6 = nextState(s6, bit, 6);
