					isss.rd = new rdbuf( (const uint8_t *)in, inlen );
					isss.is.Read = csc_read;
					osss.wr = new wrbuf( (uint8_t *)out, *outlen );
					osss.os.Write = csc_write;

					CSCProps p;
					uint32_t dict_size = 20 * 1024 * 1024;
					int level = 5;

