					osss.wr->writebuf( buf, CSC_PROP_SIZE );

					CSCEncHandle h = CSCEnc_Create(&p, (ISeqOutStream*)&osss, 0);
					CSCEnc_Encode(h, (ISeqInStream*)&isss, 0);
					CSCEnc_Encode_Flush(h);
					CSCEnc_Destroy(h);

